/*
 * Vector Clocks: Mathematical Foundation & Algorithm
 *
 * In a distributed or multi-threaded system, physical wall-clock timestamps
 * cannot determine causal ordering due to clock drift and core scheduling.
 * Vector clocks (Fidge 1988, Mattern 1989) assign each thread t a vector V_t
 * of size N (where N is the number of threads).
 *
 * Semantics:
 * - V_t[t] represents the number of logical events generated by thread t itself.
 * - V_t[u] (where u != t) represents the latest event of thread u that thread t
 *   causally knows about (via message passing, fork/join, or locks).
 *
 * Causality Theorem:
 * Event e1 in thread A happens-before event e2 in thread B (e1 -> e2) iff:
 *   e1.clock <= e2.clock AND e1.clock != e2.clock.
 *
 * FastTrack O(1) Epoch Optimization:
 * For a specific historical event e1 in thread A occurring at logical time epoch (A@c),
 * e1 -> e2 holds if and only if:
 *   c <= e2.clock[A]
 * This reduces the expensive O(N) vector comparison to an O(1) array lookup!
 */

#include "vector_clock.h"
#include <stdio.h>
#include <string.h>

/* Initialize all thread clocks to zero */
void vc_init(vector_clock_t *vc) {
    if (!vc) return;
    memset(vc->clock, 0, sizeof(vc->clock));
}

/* Deep copy src vector clock to dst */
void vc_copy(vector_clock_t *dst, const vector_clock_t *src) {
    if (!dst || !src) return;
    memcpy(dst->clock, src->clock, sizeof(dst->clock));
}

/* Advance local logical time: increment tid's own component */
void vc_increment(vector_clock_t *vc, uint32_t tid) {
    if (!vc || tid >= TS_MAX_THREADS) return;
    vc->clock[tid]++;
}

/* Pointwise maximum: merge causal knowledge from another thread/synchronization point */
void vc_join(vector_clock_t *dst, const vector_clock_t *src) {
    if (!dst || !src) return;
    for (uint32_t i = 0; i < TS_MAX_THREADS; i++) {
        if (src->clock[i] > dst->clock[i]) {
            dst->clock[i] = src->clock[i];
        }
    }
}

/*
 * Full vector clock happens-before comparison (O(N)):
 * Returns true if and only if:
 *   forall i: a->clock[i] <= b->clock[i]
 *   AND exists j: a->clock[j] < b->clock[j]
 */
bool vc_happens_before(const vector_clock_t *a, const vector_clock_t *b) {
    if (!a || !b) return false;
    bool strictly_less = false;
    for (uint32_t i = 0; i < TS_MAX_THREADS; i++) {
        if (a->clock[i] > b->clock[i]) {
            return false;
        }
        if (a->clock[i] < b->clock[i]) {
            strictly_less = true;
        }
    }
    return strictly_less;
}

/*
 * FastTrack Epoch Comparison (O(1)):
 * Checks whether an event occurring at thread 'a_tid' with logical timestamp 'a_epoch'
 * happens-before the state represented by vector clock 'b'.
 */
bool vc_happens_before_epoch(uint32_t a_tid, uint32_t a_epoch, const vector_clock_t *b) {
    if (!b || a_tid >= TS_MAX_THREADS) return false;
    return a_epoch <= b->clock[a_tid];
}

void vc_to_string(const vector_clock_t *vc, char *buf, size_t max_len) {
    if (!vc || !buf || max_len == 0) return;
    
    /* Find highest non-zero tid for compact readable output */
    int highest = -1;
    for (int i = TS_MAX_THREADS - 1; i >= 0; i--) {
        if (vc->clock[i] > 0) {
            highest = i;
            break;
        }
    }
    
    if (highest < 0) {
        snprintf(buf, max_len, "[]");
        return;
    }
    
    size_t offset = 0;
    offset += snprintf(buf + offset, max_len > offset ? max_len - offset : 0, "[");
    for (int i = 0; i <= highest; i++) {
        offset += snprintf(buf + offset, max_len > offset ? max_len - offset : 0,
                           "%u%s", vc->clock[i], (i < highest) ? "," : "");
        if (offset >= max_len - 1) break;
    }
    snprintf(buf + offset, max_len > offset ? max_len - offset : 0, "]");
}
